#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "$0")/.."

# ponytail: uses npx so nothing needs installing. Install the CLI and this picks it up.
sb() {
  if command -v supabase >/dev/null 2>&1; then supabase "$@"; else npx --yes supabase "$@"; fi
}

# local.properties is read by java.util.Properties, which keeps quotes, so write_env cannot be used.
set_property() {
  local tmp; tmp=$(mktemp)
  grep -vE "^$1=" local.properties > "$tmp" 2>/dev/null || true
  printf '%s=%s\n' "$1" "$2" >> "$tmp"
  cat "$tmp" > local.properties
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s → local.properties\n' "$GREEN" "$RESET" "$1"
}

run_wizard() {

ENV_FILE=.setup.env
TOTAL_STAGES=9

banner "Pixelock online setup"

stage "Supabase: make a project"
say "Supabase holds your groups and daily totals. The free plan is enough."
open_url "https://supabase.com/dashboard/projects"
step "Sign in or make an account."
step "Press New project. Pick the Free plan and the region closest to your friends."
step "Set a database password and save it in your password manager."
step "Wait until the project is ready."
note "The address bar then shows /project/<ref>. The ref is that string of letters."
ask PROJECT_REF "Paste the project ref:"
write_env PROJECT_REF "$PROJECT_REF"
SUPABASE_URL="https://$PROJECT_REF.supabase.co"
set_property SUPABASE_URL "$SUPABASE_URL"
pause "Press Enter to continue"

stage "Supabase: public key"
open_url "https://supabase.com/dashboard/project/$PROJECT_REF/settings/api-keys"
step "Open the Publishable and secret API keys tab."
step "Copy the publishable key. It starts with sb_publishable_."
note "This key is public and ships in the APK. Never paste a sb_secret_ key here."
ask PUBLISHABLE_KEY "Paste the publishable key:"
if [[ "$PUBLISHABLE_KEY" == sb_secret_* ]]; then
  warn "That is a secret key. Stopping so it does not end up in the APK."
  exit 1
fi
write_env PUBLISHABLE_KEY "$PUBLISHABLE_KEY"
set_property SUPABASE_ANON_KEY "$PUBLISHABLE_KEY"
pause "Press Enter to continue"

stage "Supabase: allow anonymous sign in"
say "Friends need no account. Each phone signs in anonymously."
open_url "https://supabase.com/dashboard/project/$PROJECT_REF/auth/providers"
step "Find Allow anonymous sign-ins. Turn it on and save."
note "If the menu moved, search the dashboard for: anonymous."
pause "Press Enter when that is on"

stage "Database and functions"
say "This signs the CLI in, links this folder, creates the tables and deploys the code."
sb login
note "The next command asks for the database password."
sb link --project-ref "$PROJECT_REF"
sb db push
sb functions deploy create-order --no-verify-jwt
sb functions deploy join --no-verify-jwt
sb functions deploy razorpay-webhook --no-verify-jwt
pause "Press Enter to continue"

stage "Razorpay: paid unlocks (you can skip this)"
say "Groups and invites work without this. Only Pay to open and Pay to end need it."
if confirm "Set up Razorpay now?"; then
  warn "Use Test Mode first. Live payments need your KYC and business details approved."
  open_url "https://dashboard.razorpay.com/app/keys"
  step "Make a key pair in API Keys, and copy both parts."
  ask RAZORPAY_KEY_ID "Paste the Key Id:"
  ask_secret RAZORPAY_KEY_SECRET "Paste the Key Secret:"
  WEBHOOK_SECRET=$(openssl rand -hex 24)
  open_url "https://dashboard.razorpay.com/app/webhooks"
  step "Add a webhook with this URL:"
  say "$SUPABASE_URL/functions/v1/razorpay-webhook"
  step "Use this secret:"
  say "$WEBHOOK_SECRET"
  step "Tick the payment_link.paid event, then save."
  note "If a menu name differs, look under Account & Settings."
  ask UNLOCK_PRICE_PAISE "Unlock price in paise (1000 is 10 rupees):"
  write_env RAZORPAY_KEY_ID "$RAZORPAY_KEY_ID"
  write_env UNLOCK_PRICE_PAISE "$UNLOCK_PRICE_PAISE"
  secrets=$(mktemp)
  trap 'rm -f "$secrets"' EXIT
  printf 'RAZORPAY_KEY_ID=%s\nRAZORPAY_KEY_SECRET=%s\nRAZORPAY_WEBHOOK_SECRET=%s\nUNLOCK_PRICE_PAISE=%s\n' \
    "$RAZORPAY_KEY_ID" "$RAZORPAY_KEY_SECRET" "$WEBHOOK_SECRET" "$UNLOCK_PRICE_PAISE" > "$secrets"
  sb secrets set --env-file "$secrets"
  rm -f "$secrets"
else
  SKIPPED+=("Razorpay: pay buttons show a server error until this is set up. Re-run this script.")
fi
pause "Press Enter to continue"

stage "Passcode for the hidden screen"
say "Friends get the same app as you. This passcode keeps them off the kill switch."
warn "Only you can then remove the app from a friend's phone. Tell them before they install."
note "Only a salted hash goes in the APK, so use 10 or more characters and save it somewhere safe."
if grep -q '^ADMIN_PASSCODE_HASH=' local.properties 2>/dev/null && ! confirm "A passcode is set. Change it?"; then
  note "Keeping the passcode you have."
else
  while :; do
    printf '  %sNew passcode:%s ' "$BOLD" "$RESET"; read -rs passcode; printf '\n'
    printf '  %sSame again:%s ' "$BOLD" "$RESET"; read -rs again; printf '\n'
    [[ "$passcode" == "$again" && ${#passcode} -ge 10 ]] && break
    warn "They must match and be 10 or more characters."
  done
  salt=$(openssl rand -base64 16)
  # Same as EndPassword.hash. Passed by env so the passcode never shows in a process list.
  hash=$(PIXELOCK_PASSCODE="$passcode" PIXELOCK_SALT="$salt" python3 -c '
import base64, hashlib, os
key = hashlib.pbkdf2_hmac("sha256", os.environ["PIXELOCK_PASSCODE"].encode(), base64.b64decode(os.environ["PIXELOCK_SALT"]), 120000, 32)
print(base64.b64encode(key).decode())')
  unset passcode again
  set_property ADMIN_PASSCODE_SALT "$salt"
  set_property ADMIN_PASSCODE_HASH "$hash"
fi
pause "Press Enter to continue"

stage "Build the app and upload it"
say "Invite links send friends without the app to this APK."
./gradlew assembleRelease --console=plain -q
if ! sb storage cp --experimental --linked --content-type application/vnd.android.package-archive \
    app/build/outputs/apk/release/app-release.apk ss:///app/pixelock.apk; then
  warn "The upload failed. Upload it by hand:"
  open_url "https://supabase.com/dashboard/project/$PROJECT_REF/storage/buckets/app"
  step "Upload app/build/outputs/apk/release/app-release.apk and name it pixelock.apk."
fi
pause "Press Enter to continue"

stage "Check the live server"
check_status() {
  local got; got=$(curl -s -o /dev/null -w '%{http_code}' "${@:3}" "$2" || true)
  if [[ "$got" == "$1" ]]; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$2"
  else
    warn "expected $1, got $got: $2"
    SKIPPED+=("Check failed ($got): $2")
  fi
}
check_status 200 "$SUPABASE_URL/auth/v1/signup" -X POST -H "apikey: $PUBLISHABLE_KEY" \
  -H 'content-type: application/json' -d '{}'
token=$(curl -s -X POST "$SUPABASE_URL/auth/v1/signup" -H "apikey: $PUBLISHABLE_KEY" -H 'content-type: application/json' -d '{}' |
  python3 -c 'import json, sys; print(json.load(sys.stdin).get("access_token", ""))' || true)
check_status 200 "$SUPABASE_URL/rest/v1/rpc/create_group" -X POST -H "apikey: $PUBLISHABLE_KEY" \
  -H "authorization: Bearer $token" -H 'content-type: application/json' -d '{"p_alias":"Check","p_name":"Check"}'
check_status 204 "$SUPABASE_URL/rest/v1/rpc/delete_my_data" -X POST -H "apikey: $PUBLISHABLE_KEY" \
  -H "authorization: Bearer $token" -H 'content-type: application/json' -d '{}'
check_status 302 "$SUPABASE_URL/functions/v1/join?c=2222222222222222"
check_status 200 "$SUPABASE_URL/storage/v1/object/public/app/pixelock.apk" -I
pause "Press Enter to continue"

stage "Put it on your phone"
say "If Pixelock Debug is on your phone, turn off its uninstall lock on the hidden screen and uninstall it."
say "Plug in the phone with USB debugging on, then run:"
say "adb install -r app/build/outputs/apk/release/app-release.apk"
say "After that, open Friends, make a group, and open it to invite people."
warn "Back up ~/.android/debug.keystore. It signs this APK. Lose it and friends must reinstall."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
